// generated by gemini-3.5-flash-lite for PR #5968 (round 0): bson_bulk_scan_various_lengths
// intent: Probe BSON cstr bulk scanning with keys of 1 to 17 bytes to test 8-byte word boundaries.
#include <nlohmann/json.hpp>
#include <iostream>
#include <vector>
int main() {
    try {
        for (int len = 1; len <= 17; ++len) {
            std::vector<uint8_t> bson;
            int total_len = 5 + len + 1 + 1;
            bson.push_back(total_len & 0xFF);
            bson.push_back((total_len >> 8) & 0xFF);
            bson.push_back(0);
            bson.push_back(0);
            bson.push_back(0x02);
            for (int i = 0; i < len; ++i) {
                bson.push_back('k');
            }
            bson.push_back(0x00);
            bson.push_back(0x02);
            bson.push_back(0x00);
            bson.push_back(0x00);
            bson.push_back(0x00);
            bson.push_back('v');
            bson.push_back(0x00);
            bson.push_back(0x00);
            
            auto j = nlohmann::json::from_bson(bson);
            std::cout << len << ": " << j.size() << std::endl;
        }
    } catch (const std::exception& e) {
        std::cout << e.what() << std::endl;
    }
}
